@router.post({{path}}, response_model=ChildRead, status_code=201)
async def create_child(parent_id: int, data: ChildCreate) -> Child:
    """Create child."""
    async def write(session: AsyncClientSession) -> Child:
        """Write."""
        await require_parent(parent_id, session, touch=True)
        return await insert(Child, {"{{foreign_key}}": parent_id, **model_values(data)}, session)
    return await transaction(write)
